package com.argument.teachingtrial;
import com.argument.common.exception.*;
import com.argument.version.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.argument.teaching.dto.*;
import com.argument.graph.service.GraphAssembler;
import com.argument.relation.service.RelationValidator;
import com.argument.integration.StructureEngine;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.require;
import static com.argument.teachingtrial.TeachingAccess.*;

@Service @Profile("(local | test) & !prod") @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class TeachingAnswerService {
 private final TeachingAccess access;private final TeachingWorkspaceService workspace;private final TeachingScoring scoring;private final StructureEngine structures;private final TeachingTime clock;private final ObjectMapper mapper;
 public TeachingAnswerService(TeachingAccess access,TeachingWorkspaceService workspace,TeachingScoring scoring,StructureEngine structures,TeachingTime clock,ObjectMapper mapper){this.access=access;this.workspace=workspace;this.scoring=scoring;this.structures=structures;this.clock=clock;this.mapper=mapper;}
 private ObjectNode base(Actor actor){var n=mapper.createObjectNode();VersionJson.stamp(n,actor.id(),VersionJson.now());return n;}
 private boolean released(ObjectNode assignment){return !clock.now().isBefore(Instant.parse(assignment.path("answerOpensAt").asText()));}
 private void beforeDeadline(ObjectNode assignment){require(clock.now().isBefore(Instant.parse(assignment.path("dueAt").asText())),ErrorCode.LOCKED_RESOURCE,"作业已截止，不能保存或提交新作答");}
 private List<ObjectNode> attempts(String assignment,String student){return access.data.find("teachingAnswer","assignmentId",assignment).stream().filter(a->student.equals(a.path("studentUserId").asText())).sorted(Comparator.comparingInt(a->a.path("attemptNumber").asInt())).toList();}
 private ObjectNode ownAnswer(Actor actor,String id){access.actor(actor,"STUDENT","STUDENT_ANSWER_WORK");var n=access.data.read("teachingAnswer",VersionJson.uuid(id));require(actor.id().equals(n.path("studentUserId").asText()),ErrorCode.FORBIDDEN,"只能操作本人作答");access.studentAssignment(actor,n.path("assignmentId").asText());return n;}
 private ObjectNode answerMeta(ObjectNode n){var s=n.deepCopy();s.retain("id","assignmentId","studentUserId","attemptNumber","status","recordVersion","createdAt","submittedAt","exerciseMode","resultId");return s;}
 public ObjectNode studentContext(Actor supplied,String assignmentId){var actor=access.actor(supplied,"STUDENT","STUDENT_ANSWER_WORK");var a=access.studentAssignment(actor,assignmentId);var dataset=workspace.dataset(a);var out=mapper.createObjectNode().put("mode","D_BRANCH_TRIAL");var safe=a.deepCopy();safe.retain("id","name","courseId","dueAt","answerOpensAt","maxAttempts","exerciseMode","exerciseType","status");out.set("assignment",safe);var material=out.putObject("material");var scope=dataset.path("scope");String text=dataset.path("text").path("normalizedText").asText();material.put("scopeText",text.substring(scope.path("startOffset").asInt(),scope.path("endOffset").asInt())).put("offsetBase",scope.path("startOffset").asInt());var labels=material.putArray("labels");for(var l:dataset.path("labels")){var row=((ObjectNode)l).deepCopy();row.retain("id","code","name","category","definition","enabled","status");labels.add(row);}if("RELATION_GUIDED".equals(a.path("exerciseMode").asText())){var given=material.putArray("givenElements");for(var e:dataset.path("elements"))if(e.path("isProposition").asBoolean()){var row=((ObjectNode)e).deepCopy();row.retain("id","displayNo","labelCode","text","startOffset","endOffset","isProposition");given.add(row);}}
  out.put("canCreate",clock.now().isBefore(Instant.parse(a.path("dueAt").asText())));var history=out.putArray("attempts");out.putNull("draft");for(var n:attempts(assignmentId,actor.id())){history.add(answerMeta(n));if("DRAFT".equals(n.path("status").asText())){var draft=answerMeta(n);draft.set("payload",n.path("payload"));draft.set("elements",n.path("snapshot").path("elements"));draft.set("graph",n.path("studentGraph"));out.set("draft",draft);out.put("canCreate",false);}}return out;
 }
 @Transactional public ObjectNode createAttempt(Actor supplied,String assignmentId,String key,ObjectNode body){var actor=access.actor(supplied,"STUDENT","STUDENT_ANSWER_WORK");fields(body,Set.of("reason"),Set.of());text(body,"reason",1000);var a=access.lockAssignment(actor,assignmentId,false,"");var cached=access.receipt(actor,"ATTEMPT:"+assignmentId,key,body);if(cached!=null)return cached;require(TeachingScoring.version().equals(a.path("scoringRuleVersion").asText()),ErrorCode.CONFLICT,"作业绑定的旧评分规则当前不可执行，请教师发布新版作业");beforeDeadline(a);var previous=attempts(assignmentId,actor.id());require(previous.stream().noneMatch(n->"DRAFT".equals(n.path("status").asText())),ErrorCode.CONFLICT,"已有本人草稿，请读取后继续");require(previous.stream().filter(n->"SUBMITTED".equals(n.path("status").asText())).count()<a.path("maxAttempts").asInt(),ErrorCode.CONFLICT,"已达到允许提交次数");var n=base(actor);n.put("assignmentId",assignmentId).put("courseId",a.path("courseId").asText()).put("studentUserId",actor.id()).put("attemptNumber",previous.stream().mapToInt(x->x.path("attemptNumber").asInt()).max().orElse(0)+1).put("status","DRAFT").put("exerciseMode",a.path("exerciseMode").asText()).put("standardId",a.path("standardId").asText()).put("scoringRuleVersion",a.path("scoringRuleVersion").asText()).put("datasetDigest",a.path("datasetDigest").asText()).put("reason",body.path("reason").asText()).putNull("submittedAt").putNull("resultId");var payload=n.putObject("payload");payload.putArray("elements");payload.putArray("relations");n.putObject("elementMap");n.putObject("snapshot");n.putNull("studentGraph");access.store.insert("teachingAnswer",n);var response=answerMeta(n);access.finish(actor,"ATTEMPT:"+assignmentId,key,body,response);return response;}
 @Transactional public ObjectNode save(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"STUDENT","STUDENT_ANSWER_WORK");var n=ownAnswer(actor,id);var a=access.lockAssignment(actor,n.path("assignmentId").asText(),false,"");n=access.data.lock("teachingAnswer",id);var cached=access.receipt(actor,"SAVE_ANSWER:"+id,key,body);if(cached!=null)return cached;match(n,expected);require("DRAFT".equals(n.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"已提交作答不可覆盖，请新建练习");beforeDeadline(a);var normalized=normalize(n,a,body);n.set("payload",body.deepCopy());n.set("snapshot",normalized.path("snapshot"));n.set("elementMap",normalized.path("elementMap"));n.set("studentGraph",normalized.path("graph"));touch(n,actor);access.data.replace("teachingAnswer",n);var response=answerMeta(n);response.set("payload",n.path("payload"));response.set("elements",n.path("snapshot").path("elements"));response.set("graph",n.path("studentGraph"));access.finish(actor,"SAVE_ANSWER:"+id,key,body,response);return response;}
 private ObjectNode normalize(ObjectNode answer,ObjectNode assignment,ObjectNode body){fields(body,Set.of("elements","relations"),Set.of());require(body.path("elements").isArray()&&body.path("elements").size()<=1000&&body.path("relations").isArray()&&body.path("relations").size()<=500,ErrorCode.VALIDATION_ERROR,"教学内容数量或类型无效");var dataset=workspace.dataset(assignment);var out=mapper.createObjectNode();var map=out.putObject("elementMap");ObjectNode basis;
  if("RELATION_GUIDED".equals(assignment.path("exerciseMode").asText())){require(body.path("elements").isEmpty(),ErrorCode.VALIDATION_ERROR,"关系专项只能编辑关系，不能覆盖题目给定命题");basis=dataset.deepCopy();var given=basis.putArray("elements");dataset.path("elements").forEach(e->{if(e.path("isProposition").asBoolean())given.add(e);});}
  else{basis=mapper.createObjectNode().put("ownerId",answer.path("id").asText());basis.putArray("relations");basis.putArray("participants");var elements=basis.putArray("elements");String text=dataset.path("text").path("normalizedText").asText();int left=dataset.path("scope").path("startOffset").asInt(),right=dataset.path("scope").path("endOffset").asInt(),number=0;var ordered=new ArrayList<ObjectNode>();for(var row:body.path("elements")){require(row instanceof ObjectNode,ErrorCode.VALIDATION_ERROR,"要素格式无效");var r=(ObjectNode)row;fields(r,Set.of("clientKey","startOffset","endOffset","labelCode"),Set.of());String key=VersionJson.uuid(r.path("clientKey").asText());require(!map.has(key)&&r.path("startOffset").isIntegralNumber()&&r.path("startOffset").canConvertToInt()&&r.path("endOffset").isIntegralNumber()&&r.path("endOffset").canConvertToInt(),ErrorCode.VALIDATION_ERROR,"要素本地编号或位置无效");int start=r.path("startOffset").asInt(),end=r.path("endOffset").asInt();require(start>=left&&end>start&&end<=right&&boundary(text,start)&&boundary(text,end),ErrorCode.OFFSET_INVALID,"要素越界或切开 UTF-16 代理对");JsonNode label=null;for(var l:dataset.path("labels"))if(l.path("code").equals(r.path("labelCode"))&&l.path("enabled").asBoolean(true)&&!Set.of("DISABLED","DELETED").contains(l.path("status").asText()))label=l;require(label!=null,ErrorCode.VALIDATION_ERROR,"要素类型不属于绑定指南");String eid=answer.path("elementMap").path(key).asText(VersionJson.uuid());map.put(key,eid);var e=mapper.createObjectNode().put("id",eid).put("ownerId",answer.path("id").asText()).put("ownerType","TEACHING_ANSWER").put("clientKey",key).put("startOffset",start).put("endOffset",end).put("text",text.substring(start,end)).put("labelCode",label.path("code").asText()).put("isProposition","PROPOSITION".equals(label.path("category").asText()));ordered.add(e);}ordered.sort(Comparator.comparingInt(e->e.path("startOffset").asInt()));int previous=left;for(var e:ordered){require(e.path("startOffset").asInt()>=previous,ErrorCode.CONFLICT,"要素位置重叠");previous=e.path("endOffset").asInt();if(e.path("isProposition").asBoolean())e.put("displayNo","P"+(++number));else e.putNull("displayNo");elements.add(e);}}
  var relations=validateTemplates(body.path("relations"),map,"RELATION_GUIDED".equals(assignment.path("exerciseMode").asText()));var parsed=scoring.parse(basis,relations);require(parsed.valid(),ErrorCode.GRAPH_INVALID,"本人关系结构无效："+parsed.issues().stream().filter(i->"ERROR".equals(i.level())).map(i->i.message()).findFirst().orElse("未知问题"));var source=structures.source(TeachingSnapshot.rows(basis,"elements"));var assembled=new GraphAssembler(new RelationValidator(source)).assemble(source.findBySnapshot(basis.path("ownerId").asText()).stream().filter(p->p.proposition()).toList(),parsed.views());var graph=mapper.createObjectNode();graph.set("nodes",mapper.valueToTree(assembled.nodes()));graph.set("edges",mapper.valueToTree(assembled.edges()));graph.put("componentCount",assembled.componentCount());out.set("graph",graph);var safeBasis=mapper.createObjectNode().put("ownerId",basis.path("ownerId").asText());safeBasis.set("elements",basis.path("elements"));out.set("snapshot",safeBasis);out.set("templates",mapper.valueToTree(relations));return out;
 }
 private static boolean boundary(String t,int p){return p==0||p==t.length()||!Character.isHighSurrogate(t.charAt(p-1))||!Character.isLowSurrogate(t.charAt(p));}
 private List<RelationTemplate> validateTemplates(JsonNode rows,ObjectNode ids,boolean guided){var list=new ArrayList<RelationTemplate>();var refs=new HashSet<String>();for(var raw:rows){require(raw instanceof ObjectNode,ErrorCode.VALIDATION_ERROR,"关系格式无效");var n=(ObjectNode)raw;fields(n,Set.of("ref","code","participants"),Set.of());String ref=VersionJson.uuid(n.path("ref").asText());require(refs.add(ref)&&Set.of("S","A","J","M","I").contains(n.path("code").asText())&&n.path("participants").isArray()&&n.path("participants").size()<=100,ErrorCode.VALIDATION_ERROR,"关系编号、类型或参与项无效");var parts=new ArrayList<TemplateParticipant>();int ordinal=0;for(var rawP:n.path("participants")){require(rawP instanceof ObjectNode,ErrorCode.VALIDATION_ERROR,"参与项格式无效");var p=(ObjectNode)rawP;fields(p,Set.of("role","targetKind","targetId","targetRef"),Set.of());String kind=p.path("targetKind").asText(),role=p.path("role").asText();require(Set.of("SOURCE","TARGET","MEMBER").contains(role)&&Set.of("ELEMENT","RELATION").contains(kind),ErrorCode.VALIDATION_ERROR,"未知参与项类型或角色");String target=null,targetRef=null;if("ELEMENT".equals(kind)){require(p.path("targetRef").isNull(),ErrorCode.VALIDATION_ERROR,"命题参与项不能带关系引用");String input=VersionJson.uuid(p.path("targetId").asText());target=guided?input:ids.path(input).asText();require(!target.isBlank(),ErrorCode.INVALID_PARTICIPANT,"参与项没有对应本人要素");}else{require(p.path("targetId").isNull(),ErrorCode.VALIDATION_ERROR,"关系参与项不能带要素 ID");targetRef=VersionJson.uuid(p.path("targetRef").asText());}parts.add(new TemplateParticipant(++ordinal,role,kind,target,targetRef));}list.add(new RelationTemplate(ref,n.path("code").asText(),parts,null));}return list;}
 @Transactional public ObjectNode submit(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=access.actor(supplied,"STUDENT","STUDENT_ANSWER_WORK");fields(body,Set.of("confirmed"),Set.of());require(body.path("confirmed").isBoolean()&&body.path("confirmed").asBoolean(),ErrorCode.VALIDATION_ERROR,"请确认提交");var n=ownAnswer(actor,id);var a=access.lockAssignment(actor,n.path("assignmentId").asText(),false,"");n=access.data.lock("teachingAnswer",id);var cached=access.receipt(actor,"SUBMIT_ANSWER:"+id,key,body);if(cached!=null)return cached;match(n,expected);require(TeachingScoring.version().equals(a.path("scoringRuleVersion").asText()),ErrorCode.CONFLICT,"作业绑定的旧评分规则当前不可执行，请教师发布新版作业");beforeDeadline(a);require("DRAFT".equals(n.path("status").asText())&&attempts(a.path("id").asText(),actor.id()).stream().filter(x->"SUBMITTED".equals(x.path("status").asText())).count()<a.path("maxAttempts").asInt(),ErrorCode.LOCKED_RESOURCE,"作答已提交或次数用尽");var normalized=normalize(n,a,(ObjectNode)n.path("payload"));var dataset=workspace.dataset(a);if("FULL_CASE".equals(a.path("exerciseMode").asText())){int next=dataset.path("scope").path("startOffset").asInt();for(var e:normalized.path("snapshot").path("elements")){require(e.path("startOffset").asInt()==next,ErrorCode.VALIDATION_ERROR,"完整案例作答必须覆盖范围，不能遗漏或重叠");next=e.path("endOffset").asInt();}require(next==dataset.path("scope").path("endOffset").asInt(),ErrorCode.VALIDATION_ERROR,"完整案例尚未覆盖全部范围");}
  var result=base(actor);result.put("answerId",id).put("assignmentId",a.path("id").asText()).put("courseId",a.path("courseId").asText()).put("studentUserId",actor.id()).put("attemptNumber",n.path("attemptNumber").asInt()).put("standardId",a.path("standardId").asText()).put("standardDigest",a.path("standardDigest").asText()).put("datasetDigest",a.path("datasetDigest").asText()).put("scoringRuleVersion",a.path("scoringRuleVersion").asText()).put("status","RECORDED").put("submittedAt",clock.now().toString());ObjectNode grade;
  if("RELATION_GUIDED".equals(a.path("exerciseMode").asText())){List<RelationTemplate> templates=new ArrayList<>();normalized.path("templates").forEach(t->templates.add(mapper.convertValue(t,RelationTemplate.class)));grade=scoring.score(result.path("id").asText(),a.path("exerciseType").asText(),dataset,templates);}else grade=mapper.createObjectNode().put("algorithmVersion",TeachingScoring.version()).put("scoreStatus","PENDING_BOUNDARY_AND_ELEMENT_RULES").putNull("totalScore").putNull("relationSpecialistScore");
  result.put("gradeDigest",VersionJson.canonicalHash(grade));var gradeHolder=mapper.createObjectNode().put("id",result.path("id").asText());gradeHolder.set("grade",grade);access.store.insert("teachingGradeSnapshot",gradeHolder);access.store.insert("teachingResult",result);n.put("status","SUBMITTED").put("submittedAt",clock.now().toString()).put("resultId",result.path("id").asText());n.set("snapshot",normalized.path("snapshot"));n.set("studentGraph",normalized.path("graph"));touch(n,actor);access.data.replace("teachingAnswer",n);var immutable=mapper.createObjectNode().put("id",id);immutable.set("answer",n.deepCopy());access.store.insert("teachingAttemptSnapshot",immutable);var response=answerMeta(n);response.put("scoreAvailability",released(a)?"AVAILABLE":"HELD");access.finish(actor,"SUBMIT_ANSWER:"+id,key,body,response);return response;
 }
 public ObjectNode result(Actor supplied,String id){var actor=access.fresh(supplied);var r=access.data.read("teachingResult",VersionJson.uuid(id));boolean teacher=actor.role("TEACHER");var assignment=teacher?access.teacherAssignment(actor,r.path("assignmentId").asText(),"STUDENT_RESULT_VIEW"):access.studentAssignment(actor,r.path("assignmentId").asText());if(!teacher){access.actor(actor,"STUDENT","OWN_RESULT_VIEW");require(actor.id().equals(r.path("studentUserId").asText()),ErrorCode.FORBIDDEN,"只能读取本人结果");}var answer=access.data.read("teachingAttemptSnapshot",r.path("answerId").asText()).path("answer");require("SUBMITTED".equals(answer.path("status").asText()),ErrorCode.SOURCE_INCOMPLETE,"缺少独立提交快照");var out=mapper.createObjectNode().put("id",id).put("assignmentId",assignment.path("id").asText()).put("assignmentName",assignment.path("name").asText()).put("studentUserId",r.path("studentUserId").asText()).put("studentName",access.data.read("user",r.path("studentUserId").asText()).path("displayName").asText()).put("attemptNumber",r.path("attemptNumber").asInt()).put("submittedAt",r.path("submittedAt").asText()).put("answerOpensAt",assignment.path("answerOpensAt").asText()).put("scoreAvailability",teacher||released(assignment)?"AVAILABLE":"HELD").putNull("totalScore");out.set("answer",answerMeta((ObjectNode)answer));out.set("myPayload",answer.path("payload"));out.set("myElements",answer.path("snapshot").path("elements"));out.set("myGraph",answer.path("studentGraph"));
  if(teacher||released(assignment)){var grade=access.data.read("teachingGradeSnapshot",id).path("grade");require(r.path("gradeDigest").asText().equals(VersionJson.canonicalHash(grade)),ErrorCode.SOURCE_INCOMPLETE,"历史评分摘要不匹配");out.set("grading",grade);out.set("standardSnapshot",workspace.safeSnapshot(workspace.dataset(assignment)));out.put("standardVersionId",r.path("standardId").asText()).put("standardDigest",r.path("standardDigest").asText()).put("scoringRuleVersion",r.path("scoringRuleVersion").asText());var feedback=out.putArray("teacherFeedback");access.data.find("teachingFeedback","resultId",id).stream().sorted(Comparator.comparing(f->f.path("createdAt").asText())).forEach(feedback::add);}return out;
 }
 public ObjectNode results(Actor supplied){var actor=access.fresh(supplied);require(actor.role("TEACHER")||actor.role("STUDENT"),ErrorCode.FORBIDDEN,"没有教学结果权限");var out=mapper.createObjectNode().putNull("courseTotalScore");var rows=out.putArray("items");var errors=out.putObject("specialistErrorCounts");for(var r:access.data.find("teachingResult",null,null)){try{var item=result(actor,r.path("id").asText());item.remove(List.of("myPayload","myElements","myGraph","standardSnapshot"));rows.add(item);if(actor.role("TEACHER"))for(var f:item.path("grading").path("specialist").path("feedback")){String code=f.path("code").asText();errors.put(code,errors.path(code).asInt()+1);}}catch(BusinessException e){if(e.getErrorCode()!=ErrorCode.FORBIDDEN)throw e;}}return out;}
 @Transactional public ObjectNode feedback(Actor supplied,String resultId,String key,ObjectNode body){var actor=access.actor(supplied,"TEACHER","STUDENT_RESULT_VIEW");fields(body,Set.of("comment","itemFeedback"),Set.of());String comment=text(body,"comment",3000);require(body.path("itemFeedback").isArray()&&body.path("itemFeedback").size()<=500,ErrorCode.VALIDATION_ERROR,"逐项反馈数量无效");var r=access.data.read("teachingResult",VersionJson.uuid(resultId));access.lockAssignment(actor,r.path("assignmentId").asText(),true,"STUDENT_RESULT_VIEW");var cached=access.receipt(actor,"FEEDBACK:"+resultId,key,body);if(cached!=null)return cached;var own=access.data.read("teachingAttemptSnapshot",r.path("answerId").asText()).path("answer");var ids=new HashSet<String>();own.path("snapshot").path("elements").forEach(e->ids.add(e.path("id").asText()));own.path("payload").path("relations").forEach(e->ids.add(e.path("ref").asText()));for(var raw:body.path("itemFeedback")){require(raw instanceof ObjectNode,ErrorCode.VALIDATION_ERROR,"反馈格式无效");var item=(ObjectNode)raw;fields(item,Set.of("targetId","comment"),Set.of());require(ids.contains(item.path("targetId").asText()),ErrorCode.FORBIDDEN,"反馈目标不属于此学生作答");text(item,"comment",1000);}var n=base(actor);n.put("resultId",resultId).put("teacherUserId",actor.id()).put("comment",comment);n.set("itemFeedback",body.path("itemFeedback").deepCopy());access.store.insert("teachingFeedback",n);access.finish(actor,"FEEDBACK:"+resultId,key,body,n);return n;}
}
